function utIntegerFloorDivide(first, second) {
    let result = Math.trunc(first / second);
    const residue = first - result * second;
    if (residue !== 0) {
        if ((first < 0) !== (second < 0)) {
            result -= 1;
        }
    }
    if (result === 0) {
        result = 0;
    }
    return result;
}

function utIntegerModulo(first, second) {
    const result = utIntegerFloorDivide(first, second);
    return first - result * second;
}

