use strict;
use warnings;

sub ut_integer_floor_divide {
    my ($first, $second) = @_;
    my $result = int($first / $second);
    my $residue = $first - $result * $second;
    if ($residue != 0) {
        if (($first < 0) != ($second < 0)) {
            $result -= 1;
        }
    }
    if ($result == 0) {
        $result = 0;
    }
    return $result;
}

